process BISMARK_ALIGN {
    tag "${meta.id}"
    label 'process_high'

    conda "${moduleDir}/environment.yml"
    container "${workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
        ? 'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/4f/4f649b628c613bd75e37f5671cc6d088d18e46326069f6c514192e21ac15bf98/data'
        : 'community.wave.seqera.io/library/bismark_bwa-mem3:0cace1e159351cc0'}"

    input:
    tuple val(meta), path(reads)
    tuple val(meta2), path(fasta, stageAs: 'tmp/*')
    // This change mounts as directory containing the FASTA file to prevent nested symlinks
    tuple val(meta3), path(index)
    tuple val(meta4), path(bwamem3_index, stageAs: 'bwamem3_index/*')

    output:
    tuple val(meta), path("*bam"), emit: bam
    tuple val(meta), path("*report.txt"), emit: report
    tuple val(meta), path("*fq.gz"), emit: unmapped, optional: true
    tuple val("${task.process}"), val("bismark"), eval("bismark --version 2>&1 | grep -Eo '[0-9]+\\.[0-9]+\\.[0-9]+'"), topic: versions, emit: versions_bismark
    tuple val("${task.process}"), val('bwamem3'), eval("bwa-mem3 version | sed -nE '1 s/^([0-9]+(\\.[0-9]+)+).*/\\1/p'"), emit: versions_bwamem3, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    def args = task.ext.args ?: ''
    if (task.ext.prefix) {
        args += " --prefix ${task.ext.prefix}"
    }
    def fastq = meta.single_end ? reads : "-1 ${reads[0]} -2 ${reads[1]}"

    def bwamem3_mode = (args =~ /(^|\s)--(taps|illumina_5base|five_base)(\s|$)/).find()
    if (bwamem3_index && !bwamem3_mode) {
        error("bismark/align: bwamem3_index needs --illumina_5base or --taps in ext.args")
    }
    if (bwamem3_index && args.contains('--five_base_index')) {
        error("bismark/align: give the bwa-mem3 index as the bwamem3_index input or as --five_base_index in ext.args, not both")
    }
    if (bwamem3_mode && !index && !bwamem3_index && !args.contains('--five_base_index')) {
        error("bismark/align: --illumina_5base/--taps needs bwamem3_index, --five_base_index in ext.args, or an index folder holding Bwamem3_Index/")
    }
    // 5-Base and TAPS align to the unconverted genome, so the staged FASTA folder can serve as --genome
    def genome = index ?: (bwamem3_mode ? 'tmp' : '')
    if (!genome) {
        error("bismark/align: index is required")
    }
    def resolve_index = bwamem3_index ? """
    PREFIX=\$(find -L bwamem3_index/ -name '*.meth.amb' | sed 's/\\.meth\\.amb\$//')
    if [ "\$(printf '%s\\n' "\$PREFIX" | grep -c .)" -ne 1 ]; then
        echo "bwamem3_index must hold exactly one bwa-mem3 --meth index (*.meth.amb), found: \${PREFIX:-none}" >&2
        exit 1
    fi
    """ : ''
    def index_arg = bwamem3_index ? '--five_base_index "$PREFIX"' : ''

    // Give each strand instance `-p = cpus / n_instances` threads (one index load per strand,
    // byte-identical) instead of forking N --multicore chunks that each re-load the index.
    // minimap2/rammap can't take -p from bismark yet, so they keep the legacy --multicore path.
    def isMinimapLike = args.contains('--minimap2') || args.contains('--mm2') || args.contains('--rammap') || args.contains('--ram')
    if (isMinimapLike) {

        // Legacy --multicore auto-compute (unchanged) — minimap2/rammap only.
        if (!args.contains('--multicore') && task.cpus) {

            // Numbers based on recommendation by Felix for a typical mouse genome
            def ccore = 1
            def cpu_per_multicore = 3
            def mem_per_multicore = 13.GB.toBytes()
            if (args.contains('--non_directional')) {
                cpu_per_multicore = 5
                mem_per_multicore = 18.GB.toBytes()
            }

            // How many multicore splits can we afford with the cpus we have?
            ccore = ((task.cpus as int) / cpu_per_multicore) as int

            // Check that we have enough memory
            if (task.memory) {
                def mcore = (task.memory.toBytes() / mem_per_multicore) as int
                ccore = Math.min(ccore, mcore)
            }
            else {
                log.warn("Not able to define bismark align multicore based on available memory")
            }
            if (ccore > 1) {
                args += " --multicore ${ccore}"
            }
        }
    }
    else if (bwamem3_mode) {
        // One bwa-mem3 instance; bismark requires -p >= 2
        if (!(args =~ /(^|\s)(--multicore|--parallel|--threads|-p)(\s|=|\d|$)/).find()) {
            args += " -p ${Math.max(2, (task.cpus ?: 2) as int)}"
        }
    }
    else if (!args.contains('--multicore') && !args.contains('--parallel') && !args.contains('-p ') && task.cpus) {

        def n_instances = 2
        if (args.contains('--combined_index')) {
            // combined index = one both-strands pass; parallel non-directional runs two.
            n_instances = args.contains('--non_directional') && args.contains('--combined_index_parallel') ? 2 : 1
        }
        else if (args.contains('--non_directional')) {
            n_instances = 4
        }

        // bismark requires -p >= 2, so omit it below that (one thread per instance).
        def pthreads = ((task.cpus as int) / n_instances) as int
        if (pthreads >= 2) {
            args += " -p ${pthreads}"
        }
    }
    """
    ${resolve_index}
    bismark \\
        ${fastq} \\
        --genome ${genome} \\
        --bam \\
        ${index_arg} \\
        ${args}
    """

    stub:
    def prefix = task.ext.prefix ?: "${meta.id}"
    """
    touch ${prefix}.bam
    touch ${prefix}.report.txt
    """
}

process {
    withName: BISMARK_ALIGN {
        ext.args = params.bismark_args
    }
    withName: 'BWAMEM3_INDEX.*' {
        ext.args = '--meth'
    }
}

nextflow_process {

    name "Test Process BISMARK_ALIGN (5-Base and TAPS with bwa-mem3)"
    script "../main.nf"
    process "BISMARK_ALIGN"
    config './bwamem3_modes.config'

    tag "modules"
    tag "modules_nfcore"
    tag "bismark"
    tag "bismark/align"
    tag "bwamem3/index"

    setup {
        run("BWAMEM3_INDEX") {
            script "../../../bwamem3/index/main.nf"
            process {
                """
                input[0] = Channel.of([
                            [ id:'sarscov2' ],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                """
            }
        }
    }

    // Unconverted reads: in 5-Base and TAPS an unmodified C stays C, so almost every CpG is called unmethylated
    test("illumina_5base bwamem3 | paired-end | bwamem3 index directory") {

        when {
            params {
                bismark_args = '--illumina_5base --bwamem3'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = BWAMEM3_INDEX.out.index
                """
            }
        }

        then {
            def report = file(process.out.report[0][1]).text
            def cpg = (report =~ /C methylated in CpG context:\s+([0-9.]+)%/)
            def bismark_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:Bismark') }
            def bwamem3_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:bwa-mem3') }
            def threads = (bismark_cl =~ /\s-p (\d+)/)
            assertAll(
                { assert process.success },
                { assert bismark_cl.contains('--genome tmp ') },
                { assert bismark_cl.contains('--five_base_index bwamem3_index/bwamem3/genome.fasta ') },
                { assert threads.find() && bwamem3_cl.contains(" -t ${threads.group(1)} ") },
                { assert !report.contains('Library chemistry: TAPS') },
                { assert cpg.find() && (cpg.group(1) as double) < 5 },
                // getReadsMD5 hashes read sequences only; the report lines pin the alignment and call counts
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    report.readLines().findAll { line -> line && !(line =~ /(^|\s)\/\S|version|run time|Bismark report for|completed/) },
                    process.out.unmapped,
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    ).match()
                }
            )
        }
    }

    test("taps bwamem3 | paired-end | bwamem3 index directory") {

        when {
            params {
                bismark_args = '--taps --bwamem3'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = BWAMEM3_INDEX.out.index
                """
            }
        }

        then {
            def report = file(process.out.report[0][1]).text
            assertAll(
                { assert process.success },
                { assert report.contains('Library chemistry: TAPS (mC->T)') },
                // report lines pin the TAPS alignment and call counts
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    report.readLines().findAll { line -> line && !(line =~ /(^|\s)\/\S|version|run time|Bismark report for|completed/) },
                    process.out.findAll { key, val -> key.startsWith('versions') },
                    ).match()
                }
            )
        }
    }

    test("illumina_5base bwamem3 | paired-end | bwamem3 index prefix files | five_base_baseq 30") {

        when {
            params {
                bismark_args = '--illumina_5base --bwamem3 --five_base_baseq 30'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = BWAMEM3_INDEX.out.index.map { meta, dir -> [ meta, dir.listFiles().toList() ] }
                """
            }
        }

        then {
            def report = file(process.out.report[0][1]).text
            def bismark_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:Bismark') }
            assertAll(
                { assert process.success },
                { assert bismark_cl.contains('--five_base_index bwamem3_index/genome.fasta ') },
                { assert bismark_cl.contains('--five_base_baseq 30') },
                // report lines pin the call counts at --five_base_baseq 30
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    report.readLines().findAll { line -> line && !(line =~ /(^|\s)\/\S|version|run time|Bismark report for|completed/) },
                    ).match()
                }
            )
        }
    }

    // Bismark finds <genome>/Bwamem3_Index/genome.fa.*, the layout `bismark_genome_preparation --bwamem3` writes
    test("illumina_5base bwamem3 | paired-end | index folder holding Bwamem3_Index") {

        when {
            params {
                bismark_args = '--illumina_5base --bwamem3'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = BWAMEM3_INDEX.out.index.map { meta, dir ->
                    def genome = workflow.workDir.resolve('bismark_genome_bwamem3')
                    def sub = genome.resolve('Bwamem3_Index')
                    sub.mkdirs()
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true).copyTo(genome.resolve('genome.fa'))
                    dir.listFiles().findAll { f -> f.name.startsWith('genome.fasta.') }.each { f -> f.copyTo(sub.resolve(f.name.replace('genome.fasta.', 'genome.fa.'))) }
                    [ meta, genome ]
                }
                input[3] = [[:], []]
                """
            }
        }

        then {
            def report = file(process.out.report[0][1]).text
            def bismark_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:Bismark') }
            def bwamem3_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:bwa-mem3') }
            assertAll(
                { assert process.success },
                { assert bismark_cl.contains('--genome bismark_genome_bwamem3 ') },
                { assert !bismark_cl.contains('--five_base_index') },
                { assert bwamem3_cl.contains('Bwamem3_Index/genome.fa') },
                // report lines pin the alignment and call counts
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    report.readLines().findAll { line -> line && !(line =~ /(^|\s)\/\S|version|run time|Bismark report for|completed/) },
                    ).match()
                }
            )
        }
    }

    test("illumina_5base bwamem3 | paired-end | --five_base_index in ext.args") {

        when {
            params {
                bismark_args = '--illumina_5base --bwamem3 --five_base_index bismark_genome_ext/bwamem3_meth/genome.fasta'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = BWAMEM3_INDEX.out.index.map { meta, dir ->
                    def genome = workflow.workDir.resolve('bismark_genome_ext')
                    def sub = genome.resolve('bwamem3_meth')
                    sub.mkdirs()
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true).copyTo(genome.resolve('genome.fa'))
                    dir.listFiles().findAll { f -> f.name.startsWith('genome.fasta.') }.each { f -> f.copyTo(sub.resolve(f.name)) }
                    [ meta, genome ]
                }
                input[3] = [[:], []]
                """
            }
        }

        then {
            def report = file(process.out.report[0][1]).text
            def bismark_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:Bismark') }
            def bwamem3_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:bwa-mem3') }
            assertAll(
                { assert process.success },
                { assert bismark_cl.contains('--genome bismark_genome_ext ') },
                { assert bismark_cl.contains('--five_base_index bismark_genome_ext/bwamem3_meth/genome.fasta') },
                { assert bwamem3_cl.contains('bwamem3_meth/genome.fasta') },
                // report lines pin the alignment and call counts
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    report.readLines().findAll { line -> line && !(line =~ /(^|\s)\/\S|version|run time|Bismark report for|completed/) },
                    ).match()
                }
            )
        }
    }

    test("illumina_5base | paired-end | bwamem3 index directory | no --bwamem3") {

        when {
            params {
                bismark_args = '--illumina_5base'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = BWAMEM3_INDEX.out.index
                """
            }
        }

        then {
            def report = file(process.out.report[0][1]).text
            def cpg = (report =~ /C methylated in CpG context:\s+([0-9.]+)%/)
            def bismark_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:Bismark') }
            def bwamem3_cl = bam(process.out.bam[0][1]).getHeader().find { line -> line.startsWith('@PG\tID:bwa-mem3') }
            def threads = (bismark_cl =~ /\s-p (\d+)/)
            assertAll(
                { assert process.success },
                { assert bismark_cl.contains('--genome tmp ') },
                { assert bismark_cl.contains('--five_base_index bwamem3_index/bwamem3/genome.fasta ') },
                { assert !bismark_cl.contains('--bwamem3') },
                { assert threads.find() && threads.group(1) == '4' },
                { assert bwamem3_cl.contains(' -t 4 ') },
                { assert cpg.find() && (cpg.group(1) as double) < 5 },
                { assert snapshot(
                    bam(process.out.bam[0][1]).getReadsMD5(),
                    report.readLines().findAll { line -> line && !(line =~ /(^|\s)\/\S|version|run time|Bismark report for|completed/) },
                    ).match()
                }
            )
        }
    }

    test("five_base alias without any index fails") {

        when {
            params {
                bismark_args = '--five_base'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains('bismark/align: --illumina_5base/--taps needs bwamem3_index') }
            )
        }
    }

    test("bwamem3_index without --illumina_5base or --taps fails") {

        when {
            params {
                bismark_args = '--bwamem3 --five_base_baseq 30'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = BWAMEM3_INDEX.out.index
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains('bismark/align: bwamem3_index needs --illumina_5base or --taps in ext.args') }
            )
        }
    }

    test("bwamem3 mode without any index fails") {

        when {
            params {
                bismark_args = '--illumina_5base --bwamem3'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:false ],
                            [
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                            ]
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = [[:], []]
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
                { assert process.errorReport.contains('needs bwamem3_index') }
            )
        }
    }

    test("illumina_5base bwamem3 | single-end fails") {

        when {
            params {
                bismark_args = '--illumina_5base --bwamem3'
            }
            process {
                """
                input[0] = Channel.of([
                            [ id:'test', single_end:true ],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)
                ])
                input[1] = Channel.of([
                            [ id:'sarscov2'],
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ])
                input[2] = [[:], []]
                input[3] = BWAMEM3_INDEX.out.index
                """
            }
        }

        then {
            assertAll(
                { assert process.failed },
